INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(48768179, 'Dark Scorpion - Gorg the Strong', '黑蝎-强力的高戈', '黒蠍－強力のゴーグ', 'Effect Monster', 'Warrior', 'DARK', 5, 1800, 1500, '这张卡对对方造成战斗伤害时，可以从下列效果中选择1项发动： ●将对方场上1张怪兽卡弹回对方卡组最上面。 ●将对方卡组最上面1张卡送去墓地。'),
(74153887, 'Dark Scorpion - Meanae the Thorn', '黑蝎-荆棘的美奈', '黒蠍－棘のミーネ', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1800, '①：这张卡给与对方战斗伤害时，可以从以下效果选择1个发动。 ●从卡组把1张「黑蝎」卡加入手卡。 ●以自己墓地1张「黑蝎」卡为对象才能发动。那张卡加入手卡。'),
(40933924, 'Dark Scorpion Burglars', '黑蝎盗掘团', '黒蠍盗掘団', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1000, '这张卡给与对方玩家战斗伤害时，对方从卡组选择1张魔法卡送去墓地，之后卡组洗切。'),
(20858318, 'Dark Scorpion Combination', '必杀！黑蝎合击', '必殺！黒蠍コンビネーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '当自己场上存在表侧表示的「首领 扎鲁格」「黑蝎-拆除陷阱的克里夫」「黑蝎-飞速逃跑的齐克」「黑蝎-强力的高戈」「黑蝎-荆棘的美奈」时这张卡才能发动。这张卡发动的回合，这些怪兽可以对对方进行直接攻击，每只怪兽对对方造成的战斗伤害数值在此时都变成400点。'),
(40196604, 'Dark Shade', '暗影', 'ダークシェイド', 'Normal Monster', 'Fiend', 'WIND', 3, 1000, 1000, '从水晶中发射强烈的光线进行攻击。'),
(11366199, 'Dark Simorgh', '黑暗西摩格', 'ダーク・シムルグ', 'Effect Monster', 'Winged Beast', 'DARK', 7, 2700, 1000, '①：这张卡在手卡存在的场合，从自己墓地把暗属性和风属性的怪兽各1只除外才能发动。这张卡特殊召唤。 ②：这张卡在墓地存在的场合，从手卡把暗属性和风属性的怪兽各1只除外才能发动。这张卡特殊召唤。 ③：只要这张卡在怪兽区域存在，这张卡的属性也当作「风」使用。 ④：只要这张卡在怪兽区域存在，对方不能把卡盖放。'),
(41930553, 'Dark Smog', '暗黑瘴气', '暗黒の瘴気', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，选择对方墓地1只怪兽才能发动。从手卡丢弃1只恶魔族怪兽，选择的怪兽从游戏中除外。'),
(47233801, 'Dark Snake Syndrome', '黑蛇病', '黒蛇病', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每到自己的准备阶段，这张卡对双方玩家造成200点伤害。2个回合以后，每到自己的准备阶段，这个伤害都会加倍。'),
(8198621, 'Dark Soul Token', '冥界龙 亡灵龙', '冥界龍 ドラゴネクロ', 'Token', 'Zombie', NULL, NULL, NULL, NULL, NULL),
(12930501, 'Dark Spell Regeneration', '暗黑之魔再生', '暗黒の魔再生', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以对方墓地1张魔法卡为对象才能发动。那张卡在自己场上盖放。 ②：把墓地的这张卡除外，从手卡以及自己场上盖放的卡之中把1张「死者苏生」送去墓地才能发动。从自己墓地选1只「太阳神之翼神龙」无视召唤条件特殊召唤。那之后，可以选对方场上1只怪兽送去墓地。这个效果特殊召唤的怪兽在结束阶段送去墓地。'),
(81759748, 'Dark Spider', '暗黑蜘蛛', 'ダーク・スパイダー', 'Effect Monster', 'Insect', 'DARK', 1, NULL, NULL, '1回合1次，可以把自己场上表侧表示存在的1只昆虫族怪兽的等级直到结束阶段时上升2星。'),
(38167722, 'Dark Spirit Art - Greed', '暗灵术－「欲」', '闇霊術－「欲」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只暗属性怪兽解放才能发动。对方可以从手卡把1张魔法卡给人观看让这张卡的效果无效。没给观看的场合，自己从卡组抽2张卡。'),
(51993760, 'Dark Spirit of Banishment', '抹杀之邪恶灵', '抹殺の邪悪霊', 'Effect Monster', 'Fiend', 'DARK', 3, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽攻击的伤害步骤开始时，把自己的手卡·场上的这张卡送去墓地，以自己墓地1只恶魔族·8星怪兽为对象才能发动。那只怪兽效果无效特殊召唤，攻击对象转移为那只怪兽进行伤害计算。 ②：这张卡在墓地存在，恶魔族·8星怪兽被送去自己墓地的场合才能发动。这张卡加入手卡。'),
(87988305, 'Dark Spirit of Malice', '怨念之邪恶灵', '怨念の邪悪霊', 'Effect Monster', 'Fiend', 'DARK', 3, 1600, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把魔法·陷阱·怪兽的效果发动时，把手卡·场上的这张卡送去墓地，以自己墓地1只恶魔族·8星怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡在墓地存在，恶魔族·8星怪兽被送去自己墓地的场合才能发动。这张卡加入手卡。'),
(93599951, 'Dark Spirit of the Silent', '沉默的邪恶灵', '沈黙の邪悪霊', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的战斗阶段才可以发动。1只攻击怪兽的攻击无效化，改为对方的其他的表侧表示的1只怪兽攻击。（对象是守备表示的场合变攻击表示）'),
(14386013, 'Dark Spirit''s Mastery', '暗黑神秘学', 'ダーク・オカルティズム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。从自己的卡组·墓地选1张「通灵盘」或者1只恶魔族·8星怪兽加入手卡。 ②：把墓地的这张卡除外才能发动。从自己的手卡·墓地的「通灵盘」以及「死之信息」卡之中选任意数量（同名卡最多1张），用喜欢的顺序回到卡组下面。那之后，自己从卡组抽出回去的数量。这个效果在这张卡送去墓地的回合不能发动。'),
(32646477, 'Dark Strike Fighter', '暗黑俯冲轰炸机', 'ダーク・ダイブ・ボンバー', 'Synchro Monster', 'Machine', 'DARK', 7, 2600, 1800, '调整＋调整以外的怪兽1只以上 「暗黑俯冲轰炸机」的效果1回合只能使用1次。 ①：自己主要阶段1把自己场上1只怪兽解放才能发动。给与对方解放的怪兽的等级×200伤害。'),
(87917187, 'Dark Summoning Beast', '暗黑召唤神', '暗黒の召喚神', 'Effect Monster', 'Fiend', 'DARK', 5, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把这张卡解放才能发动。「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只从手卡·卡组无视召唤条件特殊召唤。这个回合，自己怪兽不能攻击。 ②：把墓地的这张卡除外才能发动。从卡组把「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只加入手卡。'),
(39613288, 'Dark Supremacy', '黑暗至尊', 'ダーク・スプレマシー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己墓地的「暗黑融合」以及有那个卡名记述的魔法卡数量的对方场上的表侧表示卡为对象才能发动。那些卡的效果直到回合结束时无效。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己的墓地·除外状态的最多5只「英雄」怪兽为对象才能发动。那些怪兽回到卡组。'),
(97383507, 'Dark Templar @Ignister', '暗骑士＠伊格尼斯者', 'ダークナイト＠イグニスター', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '卡名不同的怪兽3只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡所连接区有怪兽特殊召唤的场合才能发动（伤害步骤也能发动）。从自己墓地把4星以下的「@火灵天星」怪兽尽可能在作为这张卡所连接区的自己场上效果无效特殊召唤。 ②：这张卡战斗破坏对方怪兽时才能发动。从自己墓地选1只电子界族怪兽特殊召唤。'),
(76614003, 'Dark Tinker', '暗黑修理师', 'ダーク・リペアラー', 'Tuner Monster', 'Fiend', 'DARK', 2, 1000, 1300, '这张卡从自己场上送去墓地时，把自己卡组最上面的卡确认再回到卡组最上面或者最下面。'),
(89494469, 'Dark Titan of Terror', '暗黑魔神 梦魇', '暗黒魔神 ナイトメア', 'Normal Monster', 'Fiend', 'DARK', 4, 1300, 1100, '据说这个恶魔潜住在梦中，当猎物睡觉时便夺去其生命。'),
(300302062, 'Dark Unity', NULL, NULL, 'Skill Card', 'The Supreme K', NULL, NULL, NULL, NULL, NULL),
(83269557, 'Dark Valkyria', '暗黑女武神', 'ダーク・ヴァルキリア', 'Gemini Monster', 'Fairy', 'DARK', 4, 1800, 1050, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●只要这张卡表侧表示存在，只有1次可以给这张卡放置1个魔力指示物。这张卡放置的魔力指示物每有1个，这张卡的攻击力上升300。可以把那1个魔力指示物取除，场上1只怪兽破坏。'),
(50164989, 'Dark Verger', '暗绿芽', 'ダーク・ヴァージャー', 'Effect Monster', 'Plant', 'EARTH', 2, NULL, 1000, '自己场上有植物族的调整召唤时，这张卡可以从墓地攻击表示特殊召唤。'),
(65282484, 'Dark Voltanis', '暗黑裁决者 伏尔泰尼斯', 'ダーク・ボルテニス', 'Effect Monster', 'Fairy', 'DARK', 8, 2800, 1400, '自己对反击陷阱的发动成功的场合，可以把自己场上存在的1只暗属性怪兽解放，从手卡把这张卡特殊召唤。这个效果特殊召唤成功时，场上存在的1张卡破坏。'),
(35565537, 'Dark Witch', '女武神', 'ヴァルキリー', 'Normal Monster', 'Fairy', 'LIGHT', 5, 1800, 1700, '在神话里出现的战斗天使，用手中的枪处以天罚。'),
(65956182, 'Dark World Accession', '暗黑界的登极', '暗黒界の登極', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：双方的主要阶段才能发动。从自己的场上·墓地把恶魔族融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组融合召唤。「暗黑界」怪兽融合召唤的场合，也能把手卡的怪兽丢弃作为融合素材。 ②：这张卡在墓地存在的场合，自己主要阶段才能发动。这张卡加入手卡。那之后，从手卡选1只「暗黑界」怪兽丢弃。'),
(76672730, 'Dark World Archives', '暗黑界的文殿', '暗黒界の文殿', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡选1只「暗黑界」怪兽丢弃，自己场上的全部「暗黑界」怪兽的攻击力直到回合结束时上升这个效果丢弃的怪兽的等级×100。 ②：原本种族是恶魔族的怪兽被「暗黑界」卡的效果或者对方的效果从自己手卡丢弃的场合才能发动（伤害步骤也能发动）。选自己1张手卡丢弃。那之后，自己从卡组抽2张。'),
(10131855, 'Dark World Brainwashing', '暗黑界的洗脑', '暗黒界の洗脳', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己手卡有3张以上存在，对方把怪兽的效果发动时，以场上1只「暗黑界」怪兽为对象才能把这个效果发动。作为对象的怪兽回到持有者手卡，那个对方的效果变成「对方手卡随机选1张丢弃」。'),
(74117290, 'Dark World Dealings', '暗黑界的交易', '暗黒界の取引', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方各自从卡组抽1张。那之后，抽卡的玩家选自身1张手卡丢弃。'),
(61623148, 'Dark World Grimoire', '暗黑界的书物', '暗黒界の書物', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己的结束阶段时手卡数量限制把手卡丢弃去墓地的场合，若那之中包含有怪兽卡可以只把1只在自己场上特殊召唤。'),
(93554166, 'Dark World Lightning', '暗黑界之雷', '暗黒界の雷', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上盖放的1张卡为对象才能发动。那张盖放的卡破坏。那之后，选自己1张手卡丢弃。'),
(3167439, 'Dark World Punishment', '暗黑界的惩罚', '暗黒界の懲罰', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方把怪兽召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。那之后，从手卡选1只恶魔族怪兽丢弃。 ②：自己场上的「暗黑界」怪兽被战斗或者对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(30284022, 'Dark World Puppetry', '暗黑界的傀儡', '暗黒界の傀儡', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以双方墓地的卡合计最多3张为对象才能发动。那些卡除外。那之后，从手卡选1只恶魔族怪兽丢弃。 ②：自己主要阶段把墓地的这张卡除外，以除外的1只自己的恶魔族怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(59784896, 'Dark Zebra', '暗黑斑马', 'ダークゼブラ', 'Effect Monster', 'Beast', 'EARTH', 4, 1800, 400, '自己的准备阶段时，自己控制的怪兽只有这张卡的场合，这张卡变成守备表示。那个回合表示形式不能变更。'),
(38247752, 'Dark-Eyes Illusionist', '暗眼幻想师', 'ダーク・アイズ・イリュージョニスト', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, NULL, 1400, '反转：这张卡场上存在的时候，指定的1只怪兽永续不能攻击。'),
(45895206, 'Dark-Piercing Light', '消除黑暗的光', '闇をかき消す光', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上里侧表示的怪兽全部表侧表示。'),
(35798491, 'Darkbishop Archfiend', '暗黑主教恶魔', 'ダークビショップデーモン', 'Effect Monster', 'Fiend', 'WATER', 3, 300, 1400, '这张卡的控制者在自己的每1个准备阶段支付500基本分。当自己场上存在的名称中含有「恶魔」字样的怪兽卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出1·3·6，则使此效果无效并将其破坏。'),
(39343610, 'Darkblaze Dragon', '暗黑烈焰龙', 'ダークブレイズドラゴン', 'Effect Monster', 'Dragon', 'FIRE', 7, 1200, 1000, '①：这张卡从墓地的特殊召唤成功的场合发动。这张卡的攻击力·守备力变成原本数值的2倍。 ②：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(50383626, 'Darkest Diabolos, Lord of the Lair', '暗黑魔王 迪亚波洛斯', '闇黒の魔王ディアボロス', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的暗属性怪兽被解放的场合才能发动。这张卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能把这张卡解放，也不能作为效果的对象。 ③：把自己场上1只暗属性怪兽解放才能发动。对方选自身1张手卡回到卡组最上面或最下面。'),
(30127518, 'Darkfall', '落大穴', '落とし大穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方以表侧表示对2只以上的怪兽的特殊召唤成功时才能发动。那些怪兽全部送去墓地。并且再把和那些怪兽同名怪兽从对方的手卡·卡组送去墓地。'),
(17881964, 'Darkfire Dragon', '暗黑火炎龙', '暗黒火炎龍', 'Fusion Monster', 'Dragon', 'DARK', 4, 1500, 1250, '「火炎草」＋「小龙」'),
(5388481, 'Darkfire Soldier #1', '燃烧士兵', 'バーニングソルジャー', 'Normal Monster', 'Pyro', 'FIRE', 4, 1700, 1150, '热烈燃烧的特种部队工作者，火药专家。'),
(78861134, 'Darkfire Soldier #2', '炎之剑豪', '炎の剣豪', 'Normal Monster', 'Pyro', 'FIRE', 4, 1700, 1100, '传说不幸的剑豪跌入了火山，从此便拥有了散发出火焰的能力。'),
(25460258, 'Darkflare Dragon', '暗黑耀星龙', 'ダークフレア・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 5, 2400, 1200, '这张卡可以把自己墓地的光属性和暗属性的怪兽各1只从游戏中除外，从手卡特殊召唤。1回合1次，可以从手卡和卡组把龙族怪兽各1只送去墓地，选择自己或者对方的墓地1张卡从游戏中除外。'),
(29876529, 'Darklight', '暗之闪光', '闇の閃光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只攻击力1500以上的暗属性怪兽解放才能发动。把这个回合特殊召唤的怪兽全部破坏。'),
(76202610, 'Darklon', '暗黑怪', 'ダークロン', 'Effect Monster', 'Fiend', 'DARK', 1, 100, 100, '这张卡召唤成功时才能发动。自己场上表侧表示存在的怪兽直到结束阶段时等级上升1星并变成暗属性。'),
(51728779, 'Darklord Amdusc', '堕天使 安度西亚斯', '堕天使アムドゥシアス', 'Effect Monster', 'Fairy', 'DARK', 6, 1800, 2800, '自己对「堕天使 安度西亚斯」1回合只能有1次特殊召唤，那些①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1张「堕天使」卡丢弃，以自己墓地1张「堕天使」卡为对象才能发动。那张卡加入手卡。 ②：支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡的效果适用。那之后，墓地的那张卡回到卡组。这个效果在对方回合也能发动。'),
(85771019, 'Darklord Asmodeus', '堕天使 阿斯蒙德斯', '堕天使アスモディウス', 'Effect Monster', 'Fairy', 'DARK', 8, 3000, 2500, '这张卡不能作从卡组·墓地的特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从卡组把1只天使族怪兽送去墓地。 ②：自己场上的这张卡被破坏送去墓地的场合发动。在自己场上把1只「阿斯蒙衍生物」（天使族·暗·5星·攻1800/守1300）和1只「蒂斯衍生物」（天使族·暗·3星·攻/守1200）特殊召唤。「阿斯蒙衍生物」不会被效果破坏。「蒂斯衍生物」不会被战斗破坏。'),
(14517422, 'Darklord Contact', '堕天使的戒坛', '堕天使の戒壇', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把1只「堕天使」怪兽守备表示特殊召唤。'),
(99941223, 'Darklord Dance', '佚乐的堕天使', '佚楽の堕天使', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的手卡·场上·墓地的怪兽作为融合素材除外，把1只天使族·暗属性的融合怪兽融合召唤。「堕天使」融合怪兽融合召唤的场合，对方场上的「堕天使」怪兽也能作为融合素材。这个效果特殊召唤的怪兽的攻击力上升1000。'),
(58787301, 'Darklord Descent', '堕天使降临', '堕天使降臨', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把基本分支付一半才能发动。选对方场上1只表侧表示怪兽，从自己墓地选和那只怪兽相同等级的最多2只「堕天使」怪兽守备表示特殊召唤。'),
(55690251, 'Darklord Desire', '堕天使 迪赛亚', '堕天使ディザイア', 'Effect Monster', 'Fairy', 'DARK', 10, 3000, 2800, '这张卡不能特殊召唤。这张卡可以把1只天使族怪兽解放作上级召唤。1回合1次，自己的主要阶段时可以把这张卡的攻击力下降1000，对方场上存在的1只怪兽送去墓地。'),
(10426067, 'Darklord Djehuty', '堕天使 杰夫提', '堕天使ジェフティ', 'Effect Monster', 'Fairy', 'DARK', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「堕天使 杰胡提」以外的1只「堕天使」怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是天使族怪兽不能特殊召唤。 ②：自己场上有天使族·暗属性的融合怪兽存在的场合，把墓地的这张卡除外，以自己墓地1张「堕天使」卡或「禁忌的」速攻魔法卡为对象才能发动。那张卡加入手卡。'),
(47664723, 'Darklord Edeh Arae', '堕天使 艾德阿拉耶', '堕天使エデ・アーラエ', 'Effect Monster', 'Fairy', 'DARK', 5, 2300, 2000, '①：从墓地特殊召唤的这张卡得到以下效果。 ●这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(87990236, 'Darklord Enchantment', '魅惑的堕天使', '魅惑の堕天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只「堕天使」怪兽送去墓地才能发动。选对方场上1只表侧表示怪兽直到结束阶段得到控制权。'),
(10136446, 'Darklord Eveningstar', '黄昏的堕天使 路西法', '黄昏の堕天使ルシファー', 'Fusion Monster', 'Fairy', 'DARK', 12, 3000, 3000, '6星以上的天使族·暗属性怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从卡组把1张「堕天使」魔法卡和1张「堕天使」陷阱卡在自己场上盖放。 ②：对方不能把场上的这张卡作为效果的对象。 ③：自己·对方回合，支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡发动时的效果适用。那之后，那张卡回到卡组。'),
(84031359, 'Darklord Gulgolet', '堕天使 骨尔加尔塔', '堕天使グルガルタ', 'Effect Monster', 'Fairy', 'DARK', 6, 2400, 800, '自己对「堕天使 骼骼他」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。在自己场上把2只「堕天使衍生物」（天使族·暗·6星·攻/守0）特殊召唤。这个效果的发动后，直到回合结束时自己不是天使族怪兽不能特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「堕天使 骼骼他」以外的「堕天使」卡或「禁忌的」速攻魔法卡加入手卡。'),
(52840267, 'Darklord Ixchel', '堕天使 伊休妲姆', '堕天使イシュタム', 'Effect Monster', 'Fairy', 'DARK', 10, 2500, 2900, '自己对「堕天使 伊希塔布」1回合只能有1次特殊召唤，那些①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1张「堕天使」卡丢弃才能发动。自己从卡组抽2张。 ②：支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡的效果适用。那之后，墓地的那张卡回到卡组。这个效果在对方回合也能发动。'),
(57579381, 'Darklord Marie', '堕天使 玛丽', '堕天使マリー', 'Effect Monster', 'Fiend', 'DARK', 5, 1700, 1200, '只要这张卡在墓地存在，每次的自己的准备阶段自己回复200基本分。'),
(25451652, 'Darklord Morningstar', '堕天使 路西菲尔', '堕天使ルシフェル', 'Effect Monster', 'Fairy', 'DARK', 11, 3000, 3000, '这张卡不能特殊召唤。 ①：这张卡上级召唤成功的场合才能发动。把最多有对方场上的效果怪兽数量的「堕天使」怪兽从手卡·卡组特殊召唤。 ②：只要自己场上有其他的「堕天使」怪兽存在，对方不能把这张卡作为效果的对象。 ③：1回合1次，自己主要阶段才能发动。把场上的「堕天使」怪兽数量的卡从自己卡组上面送去墓地。自己回复这个效果送去墓地的「堕天使」卡数量×500基本分。'),
(25339070, 'Darklord Nasten', '堕天使 莫斯提马', '堕天使マスティマ', 'Effect Monster', 'Fairy', 'DARK', 7, 2600, 2600, '自己对「堕天使 莫斯提马」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，从手卡丢弃2张其他的「堕天使」卡才能发动。这张卡特殊召唤。 ②：自己·对方回合，支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡发动时的效果适用。那之后，那张卡回到卡组。'),
(18168997, 'Darklord Nergal', '堕天使 内加尔', '堕天使ネルガル', 'Effect Monster', 'Fairy', 'DARK', 8, 2700, 2500, '自己对「堕天使 内尔伽勒」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：自己的天使族怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡的效果适用。那之后，墓地的那张卡回到卡组。这个效果在对方回合也能发动。'),
(67316075, 'Darklord Nurse Reficule', '堕天使护士-蕾菲库儿', '堕天使ナース－レフィキュル', 'Effect Monster', 'Fairy', 'DARK', 4, 1400, 600, '只要这张卡在场上表侧表示存在，对方基本分回复的效果变成给与对方基本分伤害的效果。'),
(50501121, 'Darklord Rebellion', '背德的堕天使', '背徳の堕天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上（表侧表示）把1只「堕天使」怪兽送去墓地才能发动。场上1张卡破坏。'),
(11260714, 'Darklord Superbia', '堕天使 倨薄彼亚', '堕天使スペルビア', 'Effect Monster', 'Fairy', 'DARK', 8, 2900, 2400, '①：这张卡从墓地的特殊召唤成功时，以「堕天使 苏泊比亚」以外的自己墓地1只天使族怪兽为对象才能发动。那只天使族怪兽特殊召唤。'),
(88234365, 'Darklord Tezcatlipoca', '堕天使 特斯卡特利波卡', '堕天使テスカトリポカ', 'Effect Monster', 'Fairy', 'DARK', 9, 2800, 2100, '自己对「堕天使 特斯卡特利波卡」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：自己场上的「堕天使」怪兽被战斗·效果破坏的场合，可以作为代替把手卡的这张卡丢弃。 ②：支付1000基本分，以自己墓地1张「堕天使」魔法·陷阱卡为对象才能发动。那张魔法·陷阱卡的效果适用。那之后，墓地的那张卡回到卡组。这个效果在对方回合也能发动。'),
(92807548, 'Darklord Ukoback', '堕天使 乌科巴克', '堕天使ユコバック', 'Effect Monster', 'Fairy', 'DARK', 3, 700, 1000, '「堕天使 乌科巴克」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「堕天使」卡送去墓地。'),
(54527349, 'Darklord Uprising', '叛逆的堕天使', '叛逆の堕天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上（表侧表示）把1只「堕天使」怪兽送去墓地才能发动。自己的手卡·场上的怪兽作为融合素材，把1只暗属性融合怪兽融合召唤。那之后，可以让自己基本分回复因为这张卡发动而送去墓地的怪兽的攻击力的数值。'),
(40921744, 'Darklord Zerato', '堕天使 杰拉特', '堕天使ゼラート', 'Effect Monster', 'Fairy', 'DARK', 8, 2800, 2300, '自己墓地有暗属性怪兽4种类以上存在的场合，这张卡可以把1只暗属性怪兽解放作上级召唤。 ①：从手卡把1只暗属性怪兽送去墓地才能发动。对方场上的怪兽全部破坏。 ②：这张卡的①的效果发动的回合的结束阶段发动。这张卡破坏。'),
(80168720, 'Darkness Approaches', '暗之拜访', '闇の訪れ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃2张手卡。选择表侧表示的1只怪兽，变成里侧守备表示。'),
(93709215, 'Darkness Destroyer', '暗冥破坏神', 'ダークネス・デストロイヤー', 'Effect Monster', 'Fiend', 'DARK', 7, 2300, 1800, '这张卡不能特殊召唤。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡在同1次的战斗阶段中可以作2次攻击。'),
(79266769, 'Darkness Metal, the Dragon of Dark Steel', '暗钢龙 暗铁', '闇鋼龍 ダークネスメタル', 'Link Monster', 'Dragon', 'DARK', NULL, 2800, NULL, '相同种族·属性的效果怪兽2只以上 这个卡名的效果1回合只能使用1次。 ①：以1只自己墓地的怪兽或者除外的自己怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，从场上离开的场合回到持有者卡组最下面。这个效果的发动后，直到回合结束时自己不能把连接怪兽特殊召唤。'),
(60417395, 'Darkness Neosphere', '暗冥天魔 尼奥斯菲亚', 'ダークネス・ネオスフィア', 'Effect Monster', 'Fiend', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。对方怪兽的攻击宣言时，从自己的手卡·场上各把1只恶魔族怪兽送去墓地才能把这张卡从手卡特殊召唤。这张卡不会被战斗破坏。1回合1次，可以让自己场上表侧表示存在的陷阱卡全部回到手卡。'),
(83445539, 'Darkness Resonator', NULL, NULL, 'Tuner Monster', 'Fiend', 'DARK', 3, 1300, 300, NULL),
(76925842, 'Darknight Parshath', '暗黑骑士 珀耳修斯', 'ダーク・パーシアス', 'Effect Monster', 'Fairy', 'DARK', 5, 1900, 1400, '这张卡战斗破坏对方怪兽的场合，可以把自己墓地存在的1只暗属性怪兽从游戏中除外，从自己卡组抽1张卡。这张卡的攻击力上升自己墓地存在的暗属性怪兽数量×100的数值。'),
(70054514, 'Darksea Float', '暗海救生圈', 'ダークシー・フロート', 'Effect Monster', 'Machine', 'DARK', 1, NULL, 300, '场上存在的这张卡被卡的效果破坏送去墓地时，从自己卡组抽1张卡。'),
(34659866, 'Darksea Rescue', '暗海救生艇', 'ダークシー・レスキュー', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '这张卡被同调怪兽的同调召唤使用送去墓地的场合，从自己卡组抽1张卡。'),
(57662975, 'Darkstorm Dragon', '暗黑风暴龙', 'ダークストーム・ドラゴン', 'Gemini Monster', 'Dragon', 'DARK', 8, 2700, 2500, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，把自己场上1张表侧表示的魔法·陷阱卡送去墓地才能发动。场上的魔法·陷阱卡全部破坏。'),
(64414267, 'Darktellarknight Batlamyus', '炼星骑士 多禄姆', '煉獄の騎士 ヴァトライムス', 'XYZ Monster', 'Warrior', 'DARK', 4, 2600, 550, '4星「星骑士」怪兽×2 ①：只要这张卡在怪兽区域存在，场上的表侧表示怪兽变成暗属性。 ②：把这张卡1个超量素材取除，丢弃1张手卡才能发动（自己墓地的「星骑士」怪兽是7种类以上的场合，这个效果在对方回合也能发动）。把1只光属性「星骑士」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽超量召唤。'),
(1035143, 'Darkuriboh', '暗黑栗子球', 'ダークリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的恶魔族怪兽或融合怪兽成为攻击·效果的对象时，把这张卡从手卡丢弃，以那之内的1只为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏，那只怪兽在场上发动的效果不会被无效化。 ②：这张卡被效果从手卡送去墓地的场合才能发动。从自己的卡组·墓地把1张「融合」加入手卡。'),
(83584898, 'Darkworld Shackles', '魔界的足枷', '魔界の足枷', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽不能攻击，攻击力·守备力变成100。 ②：自己准备阶段发动。给与装备怪兽的控制者500伤害。'),
(43500484, 'Darkworld Thorns', '魔界的荆棘', '魔界のイバラ', 'Normal Monster', 'Plant', 'EARTH', 3, 1200, 900, '栖息在魔界的有刺灌木，将硬闯的人牢牢缠住。'),
(86271510, 'Darton the Mechanical Monstrosity', '机怪兽 达莱特龙', '機怪獣ダレトン', 'Effect Monster', 'Machine', 'DARK', 1, -1, NULL, '①：1回合1次，自己主要阶段才能发动。这张卡的原本攻击力直到对方回合结束时变成场上的怪兽的攻击力和原本攻击力的相差数值合计数值。'),
(35394356, 'Daruma Dropper', '达磨落师', '達磨落師', 'Effect Monster', 'Warrior', 'EARTH', 4, 700, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成0。这个效果在对方回合也能发动。 ②：自己场上的超量怪兽把超量素材取除来让效果发动的场合，可以作为取除的1个超量素材的代替而把墓地的这张卡除外。这个效果在这张卡送去墓地的回合不能使用。'),
(34257001, 'Dash Warrior', '冲刺战士', 'ダッシュ・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 3, 600, 1200, '这张卡攻击的场合，伤害步骤内这张卡的攻击力上升1200。'),
(84816245, 'Data Acorn Token', '闪盘橡实', 'ドングルドングリ', 'Token', 'Cyberse', NULL, NULL, NULL, NULL, NULL),
(23331401, 'Data Token', '连接流式鸟', 'リンク・ストリーマー', 'Token', 'Cyberse', NULL, NULL, NULL, NULL, NULL),
(84816244, 'Datacorn', '闪盘橡实', 'ドングルドングリ', 'Effect Monster', 'Cyberse', 'DARK', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。在自己场上把1只「软件狗衍生物」（电子界族·暗·1星·攻/守0）特殊召唤。'),
(12500059, 'Dawn Angel Kambi', '晓天使 肯比', '暁天使カムビン', 'Effect Monster', 'Fairy', 'LIGHT', 1, 500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽不存在的场合或者只有天使族怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：把包含这张卡的自己场上的天使族怪兽任意数量解放才能发动（这个效果发动的回合，自己不是天使族怪兽不能特殊召唤）。把持有和解放的怪兽的等级合计相同等级的1只天使族怪兽从卡组特殊召唤。'),
(6351548, 'Dawn Knight', '曙光骑士', '曙光の騎士', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1400, 1200, '场上的这张卡被送去墓地的场合，可以从卡组把1只光属性怪兽送去墓地。此外，这张卡从卡组送去墓地的场合，选择自己墓地1只光属性怪兽在卡组最上面放置。「曙光之骑士」的效果1回合只能使用1次。'),
(27383110, 'Dawn of the Herald', '宣告者之预言', '宣告者の預言', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「神光之宣告者」的降临必需。必须从手卡·自己场上把等级合计直到6的怪兽解放。这张卡的效果让「神光之宣告者」仪式召唤成功时，可以把自己墓地存在的这张卡从游戏中除外，选择为那次仪式召唤而解放的1只怪兽从自己墓地回到手卡。'),
(57549932, 'Dawnbreak Gardna', '黎明守卫者', 'サンライズ・ガードナー', 'Gemini Monster', 'Warrior', 'LIGHT', 3, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡的原本守备力变成2300。'),
(91336701, 'Day-Breaker the Shining Magical Warrior', '魔导耀士 破晓者', '魔導耀士 デイブレイカー', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1600, NULL, '魔法师族怪兽2只 这个卡名的②④的效果1回合各能使用1次。 ①：这张卡连接召唤的场合发动。给这张卡放置1个魔力指示物。 ②：这张卡所连接区有魔法师族怪兽特殊召唤的场合发动。给这张卡放置1个魔力指示物。 ③：这张卡的攻击力上升这张卡的魔力指示物数量×300。 ④：把这张卡2个魔力指示物取除，以场上1张卡为对象才能发动。那张卡破坏。'),
(29116732, 'Daybreaker', '破晓者', 'デイブレーカー', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1700, NULL, '这张卡特殊召唤成功时，可以从手卡把1只「破晓者」特殊召唤。'),
(95286165, 'De-Fusion', '融合解除', '融合解除', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只融合怪兽为对象才能发动。那只融合怪兽回到持有者的额外卡组。那之后，若回到额外卡组的那只怪兽的融合召唤使用过的一组融合素材怪兽在自己墓地齐集，可以把那一组在自己场上特殊召唤。'),
(19159413, 'De-Spell', '魔法除去', '魔法除去', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1张表侧表示的魔法卡或者场上盖放的1张魔法·陷阱卡为对象才能发动。那张魔法卡破坏（那张卡在场上盖放中的场合，翻开确认）。'),
(32441317, 'De-Synchro', '同步解除', 'シンクロキャンセル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只同调怪兽为对象才能发动。那只同调怪兽回到额外卡组。那之后，若作为回到额外卡组的那只怪兽的同调召唤的素材用过的一组怪兽在自己墓地齐集，可以把那一组特殊召唤。'),
(69122763, 'Deal of Phantom', '守护灵护符', '守護霊のお守り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上的表侧表示存在的1只怪兽。在回合结束前，每有1只自己墓地存在的怪兽，选择的那只怪兽的攻击力上升100。'),
(89462956, 'Dealer''s Choice', '庄家选择', 'ディーラーズ・チョイス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方玩家把卡组洗切，从卡组抽1张。那之后，双方玩家选1张手卡丢弃。'),
(14943837, 'Debris Dragon', '残骸龙', 'デブリ・ドラゴン', 'Tuner Monster', 'Dragon', 'WIND', 4, 1000, 2000, '把这张卡作为同调素材的场合，不是龙族怪兽的同调召唤不能使用，其他的同调素材怪兽必须全部是4星以外的怪兽。 ①：这张卡召唤成功时，以自己墓地1只攻击力500以下的怪兽为对象才能发动。那只怪兽攻击表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(65703851, 'Debunk', '透破拔', '透破抜き', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：手卡·墓地有怪兽的效果发动时才能发动。那个发动无效并除外。'),
(10209545, 'Decayed Commander', '腐朽的武将', '朽ち果てた武将', 'Effect Monster', 'Zombie', 'EARTH', 4, 1000, 1500, '这张卡召唤成功时，可以从手卡特殊召唤1只「僵尸虎」。这张卡对对方直接攻击成功时，对方随机丢弃1张手卡。'),
(66328392, 'Deception of the Sinful Spoils', '罪宝的欺瞒', '罪宝の欺き', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把自己的手卡·场上1只怪兽解放才能发动。从卡组把1张「蓟花」卡加入手卡。 ②：怪兽被送去对方墓地的场合，若自己场上有「蓟花」怪兽存在则能发动。对方失去1500基本分，自己回复1500基本分。 ③：魔法与陷阱区域的表侧表示的这张卡被送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。'),
(70485614, 'Decisive Battle of Golgonda', '决战的戈尔钢达', '決戦のゴルゴンダ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「大沙海 黄金戈尔工达」使用。 ②：1回合1次，自己场上的卡被战斗·效果破坏的场合，可以作为代替从额外卡组把以「阿不思的落胤」为融合素材的1只融合怪兽送去墓地。 ③：自己·对方的结束阶段，自己的场上或墓地有「阿不思的落胤」存在的场合才能发动。从手卡·卡组把1只「护宝炮妖」怪兽特殊召唤。'),
(35027493, 'Deck Devastation Virus', '魔之牌组破坏病毒', '魔のデッキ破壊ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只攻击力2000以上的暗属性怪兽解放才能发动。对方场上的怪兽，对方手卡，用对方回合计算的3回合内对方抽到的卡全部确认，那之内的攻击力1500以下的怪兽全部破坏。'),
(1149109, 'Deck Lockdown', '牌组封锁', 'デッキロック', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方不能用抽卡以外的方法从卡组把卡加入手卡，也不能作从卡组的特殊召唤。发动后第2次的自己的准备阶段时这张卡破坏。'),
(33062423, 'Decode Destruction', '解码终结', 'デコード・エンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「解码语者」为对象才能发动。那只怪兽所连接区的怪兽数量在这个回合让以下效果适用。 ●1只以上：那只怪兽的攻击力上升那些所连接区的怪兽数量×500。 ●2只以上：那只怪兽战斗破坏的怪兽在伤害计算后除外。 ●3只：那只怪兽战斗破坏对方怪兽的伤害计算后发动。对方场上的卡全部破坏。'),
(1861629, 'Decode Talker', '解码语者', 'デコード・トーカー', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '效果怪兽2只以上 ①：这张卡的攻击力上升这张卡所连接区的怪兽数量×500。 ②：自己场上的卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡所连接区1只自己怪兽解放才能发动。那个发动无效并破坏。'),
(30822527, 'Decode Talker Extended', '解码语者・扩展', 'デコード・トーカー・エクステンド', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '效果怪兽2只以上 ①：这张卡只要在怪兽区域存在，卡名当作「解码语者」使用。 ②：这张卡的攻击力上升这张卡所连接区的怪兽数量×500。 ③：自己战斗阶段，这张卡所连接区的怪兽被战斗破坏的场合或者被送去墓地的场合才能发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(61245672, 'Decode Talker Heatsoul', '解码语者・灼热燃魂', 'デコード・トーカー・ヒートソウル', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2300, NULL, '属性不同的电子界族怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的怪兽数量×500。 ②：自己·对方回合，支付1000基本分才能发动。自己抽1张。自己基本分是2000以下的场合，可以再让以下效果适用。 ●场上的这张卡除外，除「解码语者·炽热之魂」外的1只连接3以下的电子界族怪兽从额外卡组特殊召唤。'),
(20240828, 'Decoy', NULL, NULL, 'Normal Monster', 'Beast', 'LIGHT', 1, 50, 50, NULL),
(2732323, 'Decoy Dragon', '诱饵龙', 'デコイドラゴン', 'Effect Monster', 'Dragon', 'FIRE', 2, 300, 200, '①：这张卡被选择作为攻击对象的场合，以自己墓地1只7星以上的龙族怪兽为对象发动。那只怪兽特殊召唤，攻击对象转移为那只怪兽进行伤害计算。'),
(25034083, 'Decoyroid', '诱饵机人', 'デコイロイド', 'Effect Monster', 'Machine', 'WIND', 2, 300, 500, '只要这张卡在自己场上表侧表示存在，对方不能选择「诱饵机人」以外的表侧表示怪兽作为攻击对象。'),
(69542930, 'Dedication through Light and Darkness', '光与暗之洗礼', '光と闇の洗礼', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只「黑魔术师」解放才能发动。从自己的手卡·卡组·墓地选1只「混沌之黑魔术师」特殊召唤。'),
(28654932, 'Deep Dark Trap Hole', '深黑的落穴', '深黒の落とし穴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '5星以上的效果怪兽特殊召唤成功时才能发动。那些5星以上的效果怪兽从游戏中除外。'),
(17559367, 'Deep Diver', '深海潜水员', 'ディープ・ダイバー', 'Effect Monster', 'Aqua', 'WATER', 3, 1000, 1100, '这张卡被战斗破坏送去墓地的场合，战斗阶段结束时从卡组选择1张怪兽卡，放在卡组最上面。'),
(72060415, 'Deep Sea Aria', '深海的咏叹调', '深海のアリア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地把1只水属性怪兽除外才能发动。从卡组把1只4星以下的海龙族怪兽加入手卡。'),
(8495780, 'Deep Sea Artisan', '深海的工匠', '深海のアーチザン', 'Effect Monster', 'Sea Serpent', 'WATER', 1, NULL, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用水属性怪兽的效果从卡组·墓地加入手卡的场合，把这张卡给对方观看才能发动。对方手卡全部确认。 ②：这张卡特殊召唤成功的场合，从自己卡组上面把1张卡送去墓地，以「深海工匠」以外的自己墓地1只4星以下的水属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(78868119, 'Deep Sea Diva', '深海的歌姬', '深海のディーヴァ', 'Tuner Monster', 'Sea Serpent', 'WATER', 2, 200, 400, '①：这张卡召唤成功时才能发动。从卡组把1只3星以下的海龙族怪兽特殊召唤。'),
(71978434, 'Deep Sea Minstrel', '深海的吟游诗人', '深海のミンストレル', 'Tuner Monster', 'Sea Serpent', 'WATER', 3, 1200, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只水属性怪兽丢弃才能发动。把对方手卡确认，从那之中选1张卡直到结束阶段表侧表示除外。 ②：这张卡特殊召唤成功的场合，从自己卡组上面把3张卡送去墓地，以「深海吟游诗人」以外的自己墓地1只4星以下的水属性怪兽为对象才能发动。那只怪兽回到卡组最上面或者最下面。'),
(50793215, 'Deep Sea Prima Donna', '深海姬 首席歌后', '深海姫プリマドーナ', 'Synchro Tuner Monster', 'Sea Serpent', 'WATER', 7, 1500, 2700, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：以除外的1张对方的卡为对象才能发动。从卡组把1只4星以下的水属性怪兽加入手卡或特殊召唤，作为对象的卡加入对方手卡。 ②：这张卡为同调素材的同调怪兽不会成为对方怪兽的效果的对象。 ③：这张卡被送去墓地的场合，以除外的1张自己或者对方的卡为对象才能发动。那张卡回到持有者卡组。'),
(33467872, 'Deep Sea Repetiteur', '深海的音乐导师', '深海のコレペティ', 'Synchro Tuner Monster', 'Sea Serpent', 'WATER', 5, 1800, 1500, '「深海歌后」＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己·对方回合1次，从手卡丢弃1只4星以下的水属性怪兽才能发动。这张卡的攻击力直到回合结束时上升800。 ②：同调召唤的这张卡被送去墓地的场合，以「深海艺术指导」以外的自己墓地1只5星以上的水属性怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个回合，自己不是水属性怪兽不能特殊召唤。'),
(45483489, 'Deep Sea Sentry', '深海的哨兵', '深海のセントリー', 'Effect Monster', 'Sea Serpent', 'WATER', 2, 400, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡为让水属性怪兽的效果发动而被送去墓地的场合才能发动。对方选1张手卡直到结束阶段表侧表示除外。 ②：这张卡特殊召唤成功的场合，从自己卡组上面把2张卡送去墓地，以「深海哨兵」以外的自己墓地1只4星以下的水属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(8649148, 'Deep Sweeper', '深海清道鲎', 'ディープ・スィーパー', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 1300, '把这张卡解放才能发动。选择场上1张魔法·陷阱卡破坏。'),
(22804410, 'Deep-Eyes White Dragon', '渊眼白龙', 'ディープアイズ・ホワイト・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 10, NULL, NULL, '①：自己场上的表侧表示的「青眼」怪兽被战斗或者对方的效果破坏时才能发动。这张卡从手卡特殊召唤，给与对方为自己墓地的龙族怪兽种类×600伤害。 ②：这张卡召唤·特殊召唤成功的场合，以自己墓地1只龙族怪兽为对象发动。这张卡的攻击力变成和那只怪兽的攻击力相同。 ③：场上的这张卡被效果破坏的场合发动。对方场上的怪兽全部破坏。'),
(1586457, 'Deep-Space Cruiser IX', '深空巡洋舰九型', 'ディープ・スペース・クルーザー・ナイン', 'Effect Monster', 'Machine', 'LIGHT', 9, 900, 900, '这张卡可以从手卡把这张卡以外的1只机械族怪兽送去墓地，从手卡特殊召唤。'),
(13314457, 'Deepsea Macrotrema', '深海大鳗', '深海の大ウナギ', 'Effect Monster', 'Fish', 'WATER', 1, 600, 100, '这张卡从场上送去墓地时，自己场上表侧表示存在的全部水属性怪兽的攻击力直到结束阶段时上升500。'),
(28593363, 'Deepsea Shark', '深海的潜鲛', '深海に潜むサメ', 'Fusion Monster', 'Fish', 'WATER', 5, 1900, 1600, '「神鱼」＋「舌鱼」'),
(24128274, 'Deepsea Warrior', '深海战士', '深海の戦士', 'Effect Monster', 'Warrior', 'WATER', 5, 1600, 1800, '只要「海」在场上存在，这张卡不会受到魔法的效果。'),
(76353872, 'Defcon Bird', '戒备转换鸟', 'デフコンバード', 'Effect Monster', 'Cyberse', 'WIND', 3, 100, 1700, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡把这张卡以外的1只电子界族怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，自己的电子界族怪兽被选择作为攻击对象时才能发动。那只怪兽的攻击力·守备力直到那次伤害步骤结束时变成原本攻击力的2倍。那只怪兽是攻击表示的场合，可以再把那个表示形式变成守备表示。'),
(92327802, 'Defect Compiler', '缺陷编译器', 'ディフェクト・コンパイラー', 'Effect Monster', 'Cyberse', 'LIGHT', 3, 1000, 1000, '①：1回合1次，对方的效果让自己受到伤害的场合，作为代替给这张卡放置1个缺陷指示物（最多1个）。 ②：1回合1次，把这张卡1个缺陷指示物取除，以自己场上1只电子界族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升800。这个效果在对方回合也能发动。'),
(51782995, 'Defender of Nephthys', '奈芙蒂斯的护卫者', 'ネフティスの護り手', 'Effect Monster', 'Spellcaster', 'WIND', 2, 1400, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。选1张手卡破坏，从手卡把「奈芙提斯之护卫者」以外的1只4星以下的「奈芙提斯」怪兽特殊召唤。 ②：这张卡被效果破坏送去墓地的场合，下次的自己准备阶段才能发动。从卡组选「奈芙提斯之护卫者」以外的1只「奈芙提斯」怪兽破坏。'),
(82498947, 'Defender of the Ice Barrier', '冰结界的守护阵', '氷結界の守護陣', 'Tuner Monster', 'Aqua', 'WATER', 3, 200, 1600, '①：只要自己场上有其他的「冰结界」怪兽存在，持有这张卡的守备力以上的攻击力的对方怪兽不能攻击宣言。'),
(31897444, 'Defender of the Labyrinth', '冥宫的番人', '冥宮の番人', 'Link Monster', 'Warrior', 'EARTH', NULL, 1400, NULL, '通常怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：效果怪兽以外的自己场上的怪兽的攻击力上升500，对方场上的效果怪兽的攻击力下降500。 ②：这张卡被对方破坏的场合，以效果怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(2525268, 'Defender, the Magical Knight', '魔导骑士 防御者', '魔導騎士 ディフェンダー', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 2000, '①：这张卡召唤成功的场合发动。给这张卡放置1个魔力指示物（最多1个）。 ②：1回合1次，场上的魔法师族怪兽被破坏的场合，可以作为代替把那个数量的自己场上的魔力指示物取除。'),
(71417170, 'Defenders Intersect', '防御者的相交', 'ディフェンダーズ・クロス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '战斗阶段中才能发动。对方场上守备表示存在的怪兽变成表侧攻击表示，那些怪兽的效果无效化。'),
(24268052, 'Defense Draw', '护卫防壁', 'ガード・ブロック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的战斗伤害计算时才能发动。那次战斗发生的对自己的战斗伤害变成0，从自己卡组抽1张卡。'),
(96687733, 'Defense of the Temple', '神殿的守护神', '神殿の守護神', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的手卡·场上的怪兽作为融合素材，把1只地属性融合怪兽融合召唤。把有「王家的神殿」的卡名记述的自己场上的怪兽作为融合素材的场合，对方场上的表侧表示怪兽也能作为融合素材。 ②：自己场上有「王家的神殿」存在的场合，把墓地的这张卡除外才能发动。从卡组把1张「神之怒」加入手卡。'),
(59687381, 'Defense Zone', '防守区域', 'ディフェンスゾーン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：以下效果对双方玩家适用。 ●自己的主要怪兽区域有怪兽存在的场合，相同纵列的自己的魔法与陷阱区域的卡不会成为对方的效果的对象，不会被对方的效果破坏。'),
(28877100, 'Defensive Tactics', '防守战术', 'ディフェンシブ・タクティクス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在名字带有「剑斗兽」的怪兽场合才能发动，这回合内自己控制的怪兽不会被战斗破坏且自己受到的战斗伤害为0。这张卡回到自己卡组最下面。'),
(58582979, 'Defrag Dragon', '碎片重整龙', 'デフラドラグーン', 'Effect Monster', 'Dragon', 'DARK', 3, 1000, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把手卡1只其他怪兽送去墓地，从手卡特殊召唤。 ②：这张卡在墓地存在的场合，从自己墓地把这张卡以外的3只同名怪兽除外才能发动。这张卡从墓地特殊召唤。'),
(92171126, 'Deftero Enneacraft - "alazoneIA"', '纠罪巧β’－傲慢“alazoneIA”', '糾罪巧β’－「alazoneIA」', 'Pendulum Flip Effect Monster', 'Machine', 'EARTH', 1, 100, 1000, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：包含从卡组把卡加入手卡效果的卡的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。从卡组把1张「纠罪巧」卡加入手卡。 ③：这张卡反转的场合发动。对方手卡随机选1张直到结束阶段表侧除外。'),
(37421075, 'Degen-Force', '强制退化', '強制退化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只4星以上的恐龙族怪兽解放发动。从自己的手卡·墓地把2只3星以下的爬虫类族怪兽特殊召唤。'),
(36995273, 'Degenerate Circuit', '缩退回路', '縮退回路', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，从场上回到手卡的怪兽卡不回到手卡从游戏中除外。这张卡的控制者在每次自己的准备阶段支付500基本分。这个时候不能支付500基本分的场合这张卡破坏。'),
(50426119, 'Degrade Buster', '退行手雷破坏者', 'デグレネード・バスター', 'Effect Monster', 'Cyberse', 'FIRE', 7, 2500, 2500, '这张卡不能通常召唤。把自己墓地2只电子界族怪兽除外的场合可以特殊召唤。这个卡名的效果1回合只能使用1次。 ①：以持有比这张卡的攻击力高的攻击力的对方场上1只怪兽为对象才能发动。那只怪兽直到结束阶段除外。这个效果在对方回合也能发动。'),
(87621407, 'Dekoichi the Battlechanted Locomotive', '魔装机关车 迪科伊奇', '魔装機関車 デコイチ', 'Flip Effect Monster', 'Machine', 'DARK', 4, 1400, 1000, '反转：抽1张卡。若自己场上存在表侧表示的「魔货物车辆 博科伊奇」的场合，再抽「魔货物车辆 博科伊奇」数量的卡。'),
(85718645, 'Delg the Dark Monarch', '暗帝迪尔格', '闇帝ディルグ', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2400, 1000, '这张卡召唤·特殊召唤成功时，可以把对方墓地存在的最多2张卡从游戏中除外。并且，再把除外数量的卡从对方卡组上面送去墓地。这张卡在召唤·特殊召唤的回合不能攻击。'),
(300302063, 'Delicious Morsel!', NULL, NULL, 'Skill Card', 'Camula', NULL, NULL, NULL, NULL, NULL),
(44763025, 'Delinquent Duo', '爱恶作剧的双子恶魔', 'いたずら好きな双子悪魔', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付1000基本分发动。对方随机把1张手卡丢弃，再选1张手卡丢弃。'),
(39719977, 'Delta Attacker', '三角攻势', 'デルタ・アタッカー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡仅当自己场上存在3只同名的通常怪兽（衍生物除外）时才能发动。这张卡发动的回合，这3只同名的通常怪兽可以对对方进行直接攻击。'),
(59839761, 'Delta Crow - Anti Reverse', '三角乌鸦－反埋伏', 'デルタ・クロウ－アンチ・リバース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的「黑羽」怪兽只有3只的场合，这张卡的发动从手卡也能用。 ①：自己场上有「黑羽」怪兽存在的场合才能发动。对方场上盖放的魔法·陷阱卡全部破坏。'),
(57568840, 'Delta Flyer', '三角蜻蜓龙', 'デルタフライ', 'Tuner Monster', 'Dragon', 'WIND', 3, 1500, 900, '①：1回合1次，以这张卡以外的自己场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的等级上升1星。'),
(3129133, 'Delta of Invitation', '诱惑之三角洲', '誘いのΔ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②③的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只5星以上的不死族怪兽送去墓地。 ②：场上有不死族怪兽存在的场合才能发动。在自己场上把1只「Δ衍生物」（不死族·暗·5星·攻/守0）特殊召唤。 ③：这张卡在墓地存在的状态，怪兽从墓地加入手卡的场合才能发动。这张卡加入手卡。'),
(12262393, 'Delta The Magnet Warrior', '磁石战士德尔塔', '磁石の戦士δ', 'Effect Monster', 'Rock', 'EARTH', 4, 1600, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只4星以下的「磁石战士」怪兽送去墓地。 ②：这张卡被送去墓地的场合，从自己墓地把「磁石战士δ」以外的3只4星以下的「磁石战士」怪兽除外才能发动。从手卡·卡组把1只「磁石战士 电磁武神」无视召唤条件特殊召唤。'),
(12079734, 'Delta Tri', '三角三', 'デルタトライ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1200, 1000, '这张卡战斗破坏对方怪兽的场合，从下面效果选择1个发动。 ●选择自己墓地存在的1只可以装备的同盟怪兽给这张卡装备。 ●选择自己场上表侧表示存在的1只机械族·光属性怪兽回到卡组，从自己卡组抽1张卡。'),
(59504256, 'Demigod of the Tistina', '提斯蒂娜的半神', 'ティスティナの半神', 'Effect Monster', 'Aqua', 'LIGHT', 10, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「提斯蒂娜」卡存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1张「提斯蒂娜」魔法·陷阱卡加入手卡。 ②：对方回合，自己场上有「结晶神 提斯蒂娜」存在的场合才能发动。对方场上的怪兽全部变成里侧守备表示。那之后，可以把对方场上的表侧表示卡全部送去墓地。'),
(48934760, 'Demise of the Land', '终焉之地', '終焉の地', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：对方对怪兽的特殊召唤成功时才能发动。从卡组选1张场地魔法卡发动。'),
(86124104, 'Demise, Agent of Armageddon', '终焉之魔鬼 迪米斯', '終焉の悪魔デミス', 'Ritual Effect Monster', 'Fiend', 'DARK', 4, 1800, 1000, '「世界不灭」降临。 ①：这张卡的卡名只要在手卡·场上存在当作「终焉之王 迪米斯」使用。 ②：这张卡仪式召唤成功的场合发动。选场上1只表侧表示怪兽破坏。 ③：这张卡被送去墓地的场合，以自己场上1只仪式怪兽为对象才能发动。只要那只怪兽在自己场上表侧表示存在，对方不能对应自己的仪式怪兽的效果的发动把卡的效果发动。'),
(72426662, 'Demise, King of Armageddon', '终焉之王 迪米斯', '終焉の王デミス', 'Ritual Effect Monster', 'Fiend', 'DARK', 8, 2400, 2000, '「世界末日」降临。 ①：支付2000基本分才能发动。场上的其他卡全部破坏。'),
(59913418, 'Demise, Supreme King of Armageddon', '终焉之霸王 迪米斯', '終焉の覇王デミス', 'Ritual Effect Monster', 'Fiend', 'DARK', 10, 3000, 3000, '「世界不灭」降临 ①：这张卡的卡名只要在手卡·场上存在当作「终焉之王 迪米斯」使用。 ②：只要仪式召唤的这张卡在怪兽区域存在，自己的仪式怪兽不会被战斗破坏。 ③：为只使用仪式怪兽作仪式召唤的这张卡的效果发动而支付的基本分变成不需要。 ④：1回合1次，支付2000基本分才能发动。场上的其他卡全部破坏，给与对方破坏的对方场上的卡数量×200伤害。'),
(72575145, 'Demotion', '降格处分', '降格処分', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的等级下降2星。'),
(65536818, 'Denglong, First of the Yang Zing', '源龙星－望天吼', '源竜星－ボウテンコウ', 'Synchro Tuner Monster', 'Wyrm', 'LIGHT', 5, NULL, 2800, '调整＋调整以外的怪兽1只以上 自己对「源龙星-望天吼」1回合只能有1次特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。从卡组把1张「龙星」卡加入手卡。 ②：1回合1次，从卡组把1只幻龙族怪兽送去墓地才能发动。这张卡的等级变成和送去墓地的怪兽相同。 ③：表侧表示的这张卡从场上离开的场合才能发动。从卡组把1只「龙星」怪兽特殊召唤。'),
(12890860, 'Denial Deity Dotan', '拒神 杜坦', '拒神ドゥータン', 'Fusion Monster', 'Warrior', 'LIGHT', 10, 3000, 2800, '光属性怪兽＋场上·墓地以外的怪兽×2 ①：融合召唤的这张卡不会被战斗破坏。 ②：原本卡名和对方的场上·墓地的怪兽相同的怪兽在自己的场上·墓地其中每种之内都不存在的场合，自己场上的怪兽不会被效果破坏。 ③：把原本卡名和对方的场上·墓地的怪兽相同的1只怪兽从手卡·卡组·额外卡组送去墓地，以对方的场上·墓地1只怪兽为对象才能发动。那只怪兽除外。'),
(13974207, 'Denko Sekka', '电光－雪花－', '電光－雪花－', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1700, 1000, '这张卡不能特殊召唤。 ①：这张卡在怪兽区域存在，自己场上没有盖放的魔法·陷阱卡存在的场合，双方不能把魔法·陷阱卡盖放，场上盖放的魔法·陷阱卡不能发动。'),
(10474647, 'Depresspard', '五月豹', '五月豹', 'Effect Monster', 'Beast', 'LIGHT', 2, 100, 100, '①：手卡只有这1张卡的场合才能发动。这张卡特殊召唤。 ②：这张卡的①的效果特殊召唤的场合发动。这张卡的攻击力直到对方回合结束时变成2500。 ③：这张卡和对方怪兽进行战斗的场合，那次战斗发生的对对方的战斗伤害由自己代受。 ④：这张卡的战斗让自己受到伤害的场合发动。这张卡的攻击力变成0。那之后，自己基本分是2000以下的场合，这张卡的攻击力变成5000。'),
(8279188, 'Depth Amulet', '深渊护符', 'デプス・アミュレット', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把1张手卡丢弃去墓地，让1只对方怪兽的攻击无效。这张卡在发动后第3次的对方的结束阶段时破坏。'),
(37798171, 'Depth Shark', '深鲨', 'デプス・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1400, NULL, '自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。对方的准备阶段时1次，这张卡的攻击力直到结束阶段时变成2倍。'),
(46708514, 'Derk, Longing for the Blue Skies', '凝视苍穹的蠕龙', '蒼穹を睨めるダーク', 'Effect Monster', 'Reptile', 'DARK', 10, 3000, 2700, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在墓地存在的状态，对方发动的怪兽的效果从卡组或额外卡组让怪兽特殊召唤的场合才能发动。这张卡特殊召唤。 ②：包含把怪兽特殊召唤效果的怪兽的效果发动时，从自己的手卡·场上把1张卡除外才能发动。那个效果无效并破坏。 ③：这张卡被除外的回合的结束阶段才能发动。自己的除外状态的1只其他怪兽回到墓地。'),
(39131963, 'Des Counterblow', '死亡反击', 'デスカウンター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '进行直接攻击并对玩家造成战斗伤害的怪兽被破坏。'),
(44883830, 'Des Croaking', '死之合唱', '死の合唱', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有3只「死亡青蛙」表侧表示存在时才能发动。对方场上存在的卡全部破坏。'),
(12965761, 'Des Dendle', '死亡石斛', 'デス・デンドル', 'Union Effect Monster', 'Plant', 'EARTH', 4, 300, 2000, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「血兰」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽每次战斗破坏怪兽时把1只「魔草衍生物」（植物族·地·1星·攻/守800）特殊召唤。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(81985784, 'Des Feral Imp', '死亡精怪', 'デスグレムリン', 'Flip Effect Monster', 'Reptile', 'DARK', 4, 1600, 1800, '①：这张卡反转的场合，以自己墓地1张卡为对象发动。那张卡回到卡组。'),
(84451804, 'Des Frog', '死亡青蛙', 'デスガエル', 'Effect Monster', 'Aqua', 'WATER', 5, 1900, NULL, '这张卡的祭品召唤成功时，可以把最多有自己墓地存在的「恶魂邪苦止」数量的「死亡青蛙」从手卡或者卡组特殊召唤。'),
(78613627, 'Des Kangaroo', '死亡袋鼠', 'デス・カンガルー', 'Effect Monster', 'Beast', 'DARK', 4, 1500, 1700, '①：向守备表示的这张卡进行攻击的怪兽的攻击力比这张卡的守备力低的场合，那次伤害步骤结束时发动。那只怪兽破坏。'),
(69579761, 'Des Koala', '死亡树熊', 'デス・コアラ', 'Flip Effect Monster', 'Beast', 'DARK', 3, 1100, 1800, '①：这张卡反转的场合发动。给与对方为对方手卡数量×400伤害。'),
(2326738, 'Des Lacooda', '死亡骆驼', 'デス・ラクーダ', 'Effect Monster', 'Zombie', 'EARTH', 3, 500, 600, '①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转召唤成功的场合发动。自己从卡组抽1张。'),
(33695750, 'Des Mosquito', '死亡蚊', 'デス・モスキート', 'Effect Monster', 'Insect', 'DARK', 3, 500, 500, '这张卡召唤、特殊召唤成功时，给这张卡放置2个指示物。这个效果每放置有1个指示物，这张卡的攻击力上升500。这张卡被战斗破坏的场合，把这张卡的1个指示物取除作代替。'),
(81059524, 'Des Volstgalph', '死亡魔导龙', 'デス・ヴォルストガルフ', 'Effect Monster', 'Dragon', 'EARTH', 6, 2200, 1700, '①：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方500伤害。 ②：只要这张卡在怪兽区域存在，每次自己或者对方把通常·速攻魔法卡发动，直到回合结束时这张卡的攻击力上升各200。'),
(9637706, 'Des Wombat', '死亡袋熊', 'デス・ウォンバット', 'Effect Monster', 'Beast', 'EARTH', 3, 1600, 300, '只要这张卡在场上表侧表示存在，控制者受到的卡的效果的伤害为0。'),
(42079445, 'Descending Lost Star', '失星降落', 'ロスト・スター・ディセント', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只同调怪兽为对象才能发动。那只怪兽的等级下降1星，守备力变成0守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，不能把表示形式变更。'),
(63410069, 'Desert Locusts', '沙漠的飞蝗贼', '砂漠の飛蝗賊', 'Synchro Tuner Monster', 'Insect', 'EARTH', 6, 1500, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤成功的场合发动。回合玩家选自身1张手卡丢弃。 ②：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为同调素材作同调召唤。'),
(38981606, 'Desert Protector', '沙漠守护者', '砂漠の守護者', 'Effect Monster', 'Insect', 'EARTH', 4, 800, 1000, '这张卡的守备力上升场上存在的魔法·陷阱卡数量×300的数值。自己场上存在的昆虫族怪兽被破坏的场合，可以作为代替把这张卡破坏。'),
(93747864, 'Desert Sunlight', '沙漠之光', '砂漠の光', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的所有怪兽全部变成表侧守备表示。'),
(81977953, 'Desert Twister', '荒漠龙卷怪', 'デザート・ツイスター', 'Effect Monster', 'Fiend', 'WIND', 6, 2300, 2000, '这张卡不能通常召唤。把自己墓地2只风属性怪兽和1只地属性怪兽从游戏中除外才能特殊召唤。可以丢弃1张手卡把场上1张魔法·陷阱卡破坏。这个效果1回合只能使用1次。'),
(13409151, 'Desertapir', '沙貘', '砂バク', 'Flip Effect Monster', 'Beast', 'EARTH', 3, 900, 300, '①：这张卡反转的场合，以「沙貘」以外的场上1只表侧表示怪兽为对象发动。那只怪兽变成里侧守备表示。'),
(36693940, 'Designer Frightfur', '魔玩具改造', 'デストーイ・カスタム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「锋利小鬼」怪兽或者「毛绒动物」怪兽为对象才能发动。那只怪兽特殊召唤。把这个效果特殊召唤的怪兽作为融合素材的场合，可以当作「魔玩具」怪兽使用。'),
(94693857, 'Deskbot 001', '文具博格００１', 'ブンボーグ００１', 'Tuner Monster', 'Machine', 'EARTH', 1, 500, 500, '①：这张卡的攻击力·守备力上升自己场上的机械族怪兽数量×500。 ②：这张卡在墓地存在，场上有机械族怪兽2只以上同时特殊召唤的场合才能发动。这张卡特殊召唤。'),
(59368956, 'Deskbot 002', '文具博格００２', 'ブンボーグ００２', 'Effect Monster', 'Machine', 'EARTH', 2, 500, 500, '①：这张卡特殊召唤成功的场合才能发动。从卡组把1张「文具电子人」卡加入手卡。 ②：只要这张卡在怪兽区域存在，这张卡以外的自己场上的机械族怪兽的攻击力·守备力上升500。'),
(75944053, 'Deskbot 003', '文具博格００３', 'ブンボーグ００３', 'Effect Monster', 'Machine', 'EARTH', 3, 500, 500, '①：这张卡召唤成功时才能发动。从卡组把「文具电子人003」以外的1只「文具电子人」怪兽特殊召唤。 ②：1回合1次，以自己场上1只「文具电子人」怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时上升自己场上的「文具电子人」卡数量×500。这个效果在对方回合也能发动。'),
(22227683, 'Deskbot 004', '文具博格００４', 'ブンボーグ００４', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 500, '①：这张卡和对方怪兽进行战斗的伤害计算时才能发动。从卡组把「文具电子人004」以外的1只「文具电子人」怪兽送去墓地，这张卡的攻击力·守备力只在那次伤害计算时上升送去墓地的那只怪兽的等级×500。这个效果的发动后，直到回合结束时对方受到的战斗伤害变成0。 ②：这张卡战斗破坏对方怪兽的场合才能发动。从自己的手卡·墓地选2只等级不同的「文具电子人」怪兽守备表示特殊召唤。'),
(10117149, 'Deskbot 005', '文具博格００５', 'ブンボーグ００５', 'Pendulum Effect Monster', 'Machine', 'EARTH', 5, 500, 500, '「文具电子人005」的③的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：这张卡的攻击力上升自己的额外卡组的表侧表示的「文具电子人」怪兽数量×500。 ③：这张卡在灵摆区域被破坏的场合，以自己墓地1只「文具电子人」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(55106249, 'Deskbot 006', '文具博格００６', 'ブンボーグ００６', 'Pendulum Effect Monster', 'Machine', 'EARTH', 6, 500, 500, '「文具电子人006」的③的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。 ②：这张卡的攻击力上升自己的额外卡组的表侧表示的「文具电子人」怪兽数量×500。 ③：这张卡在灵摆区域被破坏的场合，以自己墓地1张「文具电子人」卡为对象才能发动。那张卡加入手卡。'),
(97588916, 'Deskbot 007', '文具博格００７', 'ブンボーグ００７', 'Pendulum Effect Monster', 'Machine', 'EARTH', 7, 500, 500, '①：这张卡的攻击力上升自己墓地的「文具电子人」卡数量×500。 ②：只要这张卡在怪兽区域存在，对方不能把其他的「文具电子人」怪兽作为攻击对象。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(24573625, 'Deskbot 008', '文具博格００８', 'ブンボーグ００８', 'Pendulum Effect Monster', 'Machine', 'EARTH', 8, 500, 500, '①：这张卡的攻击力上升自己墓地的「文具电子人」卡数量×500。 ②：只要这张卡在怪兽区域存在，对方不能把其他的「文具电子人」卡作为效果的对象。 ③：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(25494711, 'Deskbot 009', '文具博格００９', 'ブンボーグ００９', 'Effect Monster', 'Machine', 'EARTH', 9, 500, 500, '①：1回合1次，自己主要阶段1才能发动。这张卡的攻击力直到对方回合结束时上升「文具电子人009」以外的自己场上的「文具电子人」怪兽的攻击力的合计数值。这个效果发动的回合，不用这张卡不能攻击。 ②：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ③：这张卡被战斗·效果破坏的场合，可以作为代替把自己场上1张「文具电子人」卡破坏。'),
(12215894, 'Deskbot Base', '文具博格・基地', 'ブンボーグ・ベース', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「文具电子人」怪兽的攻击力·守备力上升500。 ②：1回合1次，自己主要阶段才能发动。手卡的「文具电子人」卡任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量。 ③：把「文具电子人基地」以外的自己的场上·墓地的「文具电子人」卡9种类各1张除外才能发动。对方的手卡·场上·墓地的卡全部回到持有者卡组。'),
(89544521, 'Deskbot Jet', '文具博格・喷射机', 'ブンボーグ・ジェット', 'Synchro Monster', 'Machine', 'EARTH', 10, 500, 500, '调整＋调整以外的怪兽1只以上 「文具电子人喷气机」的②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡的攻击力·守备力上升场上的「文具电子人」卡数量×500。 ②：以自己场上1张「文具电子人」卡为对象才能发动。那张卡破坏，从卡组把1只「文具电子人」怪兽特殊召唤。 ③：以自己场上1张「文具电子人」卡和场上1张表侧表示的卡为对象才能发动。那些卡破坏。'),
(42908201, 'Desmanian Devil', '死亡马尼亚魔鬼', 'デスマニア・デビル', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 1400, '①：这张卡战斗破坏对方怪兽时才能发动。从卡组把1只4星以下的兽族怪兽加入手卡。');